1	//! Integration tests for COR24 emulator using as24-assembled .lgo files
2	
3	use cor24_emulator::cpu::executor::Executor;
4	use cor24_emulator::cpu::state::CpuState;
5	use cor24_emulator::loader::load_lgo;
6	
7	/// Assemble `source` via the standalone `cor24-asm` binary and return
8	/// the `.lgo` text. Tests in this file no longer link the in-tree
9	/// assembler — they go through the production toolchain.
10	fn asm_to_lgo(source: &str) -> String {
11	    use std::io::Write;
12	    use std::process::{Command, Stdio};
13	    let mut child = Command::new("cor24-asm")
14	        .arg("-")
15	        .stdin(Stdio::piped())
16	        .stdout(Stdio::piped())
17	        .stderr(Stdio::piped())
18	        .spawn()
19	        .expect("cor24-asm not on PATH; required by integration tests");
20	    child
21	        .stdin
22	        .as_mut()
23	        .unwrap()
24	        .write_all(source.as_bytes())
25	        .unwrap();
26	    let output = child
27	        .wait_with_output()
28	        .expect("cor24-asm wait_with_output failed");
29	    if !output.status.success() {
30	        panic!(
31	            "cor24-asm failed: status={:?}\nstderr=\n{}",
32	            output.status.code(),
33	            String::from_utf8_lossy(&output.stderr),
34	        );
35	    }
36	    String::from_utf8(output.stdout).expect("cor24-asm output not UTF-8")
37	}
38	
39	/// Load .lgo text into a fresh `CpuState` and return it. Helper for
40	/// the migrated assemble_and_run pattern below.
41	fn load_lgo_into_cpu(lgo: &str) -> CpuState {
42	    let mut cpu = CpuState::new();
43	    cpu.io.uart_tx_busy_cycles = 0; // legacy: instant TX for tests that don't poll
44	    load_lgo(lgo, &mut cpu).expect("load_lgo");
45	    cpu.pc = 0;
46	    cpu
47	}
48	
49	/// The set of `.s` source files this crate exposes as runnable examples.
50	/// (Was previously fronted by `cor24_emulator::challenge::get_examples`,
51	/// which has been deleted; this list is the test-only consumer that
52	/// remained.) When `src/assembler.rs` itself goes away in a later step,
53	/// these tests will go with it.
54	const EXAMPLES: &[(&str, &str)] = &[
55	    ("Add", include_str!("../src/examples/assembler/add.s")),
56	    ("Assert", include_str!("../src/examples/assembler/assert.s")),
57	    ("Blink LED", include_str!("../src/examples/assembler/blink_led.s")),
58	    ("Button Echo", include_str!("../src/examples/assembler/button_echo.s")),
59	    ("Comments", include_str!("../src/examples/assembler/comments.s")),
60	    ("Countdown", include_str!("../src/examples/assembler/countdown.s")),
61	    ("Echo", include_str!("../src/examples/assembler/echo.s")),
62	    ("Fibonacci", include_str!("../src/examples/assembler/fibonacci.s")),
63	    ("Literals", include_str!("../src/examples/assembler/literals.s")),
64	    ("Loop Trace", include_str!("../src/examples/assembler/loop_trace.s")),
65	    ("Memory Access", include_str!("../src/examples/assembler/memory_access.s")),
66	    ("Multiply", include_str!("../src/examples/assembler/multiply.s")),
67	    ("Nested Calls", include_str!("../src/examples/assembler/nested_calls.s")),
68	    ("Stack Variables", include_str!("../src/examples/assembler/stack_variables.s")),
69	    ("UART Hello", include_str!("../src/examples/assembler/uart_hello.s")),
70	    ("Variables", include_str!("../src/examples/assembler/variables.s")),
71	];
72	
73	/// Load an LGO file, set PC, run for max_cycles
74	fn load_and_run(lgo_path: &str, entry: u32, max_cycles: u64) -> CpuState {
75	    let content = std::fs::read_to_string(lgo_path)
