1	//! `tmp101` — TI TMP101 temperature sensor (I2C).
2	//!
3	//! Models the four chip registers the imported `tmp101.lgo` demo
4	//! cares about:
5	//!   - `0x00` — Temperature (16-bit, read-only).
6	//!   - `0x01` — Configuration (8-bit, read/write).
7	//!   - `0x02` — T_LOW   (16-bit, read/write — stub: stored verbatim).
8	//!   - `0x03` — T_HIGH  (16-bit, read/write — stub: stored verbatim).
9	//!
10	//! The 12-bit temperature value is laid out in the upper 12 bits of
11	//! the 16-bit register (0.0625°C / LSB; bits[3:0] always zero). The
12	//! current resolution mode in the config register is honoured at read
13	//! time, so a guest that reconfigures resolution between reads sees
14	//! values quantized to the new step size.
15	
16	use crate::peripherals::i2c::device::{Ack, I2cDevice};
17	
18	/// Default 7-bit address for the COR24-TB layout.
19	pub const DEFAULT_ADDRESS: u8 = 0x4A;
20	
21	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
22	pub enum Tmp101Resolution {
23	    Bits9,
24	    Bits10,
25	    Bits11,
26	    Bits12,
27	}
28	
29	impl Tmp101Resolution {
30	    fn from_config(config: u8) -> Self {
31	        match (config >> 5) & 0x03 {
32	            0b00 => Self::Bits9,
33	            0b01 => Self::Bits10,
34	            0b10 => Self::Bits11,
35	            _ => Self::Bits12,
36	        }
37	    }
38	
39	    fn mask(self) -> u16 {
40	        // Mask applied to the 12-bit temperature value before it is
41	        // shifted into the 16-bit register layout.
42	        match self {
43	            Self::Bits9 => 0x0FF8,
44	            Self::Bits10 => 0x0FFC,
45	            Self::Bits11 => 0x0FFE,
46	            Self::Bits12 => 0x0FFF,
47	        }
48	    }
49	}
50	
51	pub struct Tmp101Device {
52	    address: u8,
53	    pointer: u8,
54	    config: u8,
55	    /// Configured temperature in °C. Quantized at read time using the
56	    /// current config resolution, so set-then-reconfigure works.
57	    temperature: f32,
58	    /// Datasheet defaults: 75°C / 80°C in 12-bit register layout.
59	    t_low: u16,
60	    t_high: u16,
61	    /// Byte index within the current write transaction. 0 = next byte
62	    /// is the pointer; 1+ = data bytes for the selected register.
63	    write_idx: u8,
64	    /// Byte index within the current read transaction.
65	    read_idx: u8,
66	}
67	
68	impl Tmp101Device {
69	    pub fn new(address: u8) -> Self {
70	        Self {
71	            address: address & 0x7F,
72	            pointer: 0,
73	            config: 0,
74	            temperature: 0.0,
75	            t_low: 0x4B00,
76	            t_high: 0x5000,
77	            write_idx: 0,
78	            read_idx: 0,
79	        }
80	    }
81	
82	    /// Set the configured temperature in °C. Quantized at read time
83	    /// based on the current resolution mode.
84	    pub fn set_temperature(&mut self, celsius: f32) {
85	        self.temperature = celsius;
86	    }
87	
88	    /// Currently-configured temperature in °C (the value the guest
89	    /// would read back, given the current resolution).
90	    pub fn temperature(&self) -> f32 {
91	        let val = self.temp_register_value();
92	        // Sign-extend the 12-bit value to i32, scale by 0.0625°C/LSB.
93	        let signed = sign_extend_12(val);
94	        signed as f32 * 0.0625
95	    }
96	
97	    /// Set the configuration register directly. Useful in tests.
98	    pub fn set_config(&mut self, config: u8) {
99	        self.config = config;
100	    }
101	
102	    pub fn config(&self) -> u8 {
103	        self.config
104	    }
105	
106	    /// Set the resolution by writing the appropriate bits to config.
107	    /// Other config bits are preserved.
108	    pub fn set_resolution(&mut self, res: Tmp101Resolution) {
109	        let bits: u8 = match res {
110	            Tmp101Resolution::Bits9 => 0b00,
111	            Tmp101Resolution::Bits10 => 0b01,
112	            Tmp101Resolution::Bits11 => 0b10,
113	            Tmp101Resolution::Bits12 => 0b11,
114	        };
115	        self.config = (self.config & !0x60) | (bits << 5);
116	    }
117	
118	    pub fn resolution(&self) -> Tmp101Resolution {
119	        Tmp101Resolution::from_config(self.config)
120	    }
121	
122	    /// 12-bit temperature value as the chip would currently report it,
123	    /// quantized to the active resolution.
124	    fn temp_register_value(&self) -> u16 {
125	        let raw = (self.temperature / 0.0625).round() as i32;
126	        let clamped = raw.clamp(-2048, 2047);
127	        let val_12bit = (clamped & 0x0FFF) as u16;
128	        val_12bit & self.resolution().mask()
129	    }
130	
131	    /// 16-bit temperature register (12-bit value in the upper 12 bits;
132	    /// lower 4 bits always 0).
133	    fn temp_register(&self) -> u16 {
134	        self.temp_register_value() << 4
135	    }
136	
137	    fn read_register_byte(&self, register: u8, idx: u8) -> u8 {
138	        match register {
139	            0x00 => byte_of_u16(self.temp_register(), idx),
140	            0x01 => self.config,
141	            0x02 => byte_of_u16(self.t_low, idx),
142	            0x03 => byte_of_u16(self.t_high, idx),
143	            _ => 0xFF,
144	        }
145	    }
146	
147	    fn write_register_byte(&mut self, register: u8, idx: u8, byte: u8) {
148	        match register {
149	            0x00 => { /* temp register is read-only */ }
150	            0x01 => self.config = byte,
151	            0x02 => self.t_low = patch_u16(self.t_low, idx, byte),
152	            0x03 => self.t_high = patch_u16(self.t_high, idx, byte),
153	            _ => {}
154	        }
155	    }
156	}
157	
158	fn sign_extend_12(value: u16) -> i32 {
159	    let v = (value & 0x0FFF) as i32;
160	    if v & 0x0800 != 0 { v - 0x1000 } else { v }
161	}
162	
163	fn byte_of_u16(reg: u16, idx: u8) -> u8 {
164	    // Even index = high byte; odd = low byte. 16-bit reads on TMP101
165	    // continue past the second byte by re-reading from the start.
166	    if idx.is_multiple_of(2) {
167	        (reg >> 8) as u8
168	    } else {
169	        (reg & 0xFF) as u8
170	    }
171	}
172	
173	fn patch_u16(reg: u16, idx: u8, byte: u8) -> u16 {
174	    if idx == 1 {
175	        (reg & 0x00FF) | ((byte as u16) << 8)
176	    } else if idx == 2 {
177	        (reg & 0xFF00) | (byte as u16)
178	    } else {
179	        reg
180	    }
181	}
182	
183	impl I2cDevice for Tmp101Device {
184	    fn address(&self) -> u8 {
185	        self.address
186	    }
187	
188	    fn set_address(&mut self, addr: u8) {
189	        self.address = addr & 0x7F;
190	    }
191	
192	    fn name(&self) -> &str {
193	        "tmp101"
194	    }
195	
196	    fn on_start(&mut self) {
197	        self.write_idx = 0;
198	        self.read_idx = 0;
199	    }
200	
201	    fn on_write_byte(&mut self, byte: u8) -> Ack {
202	        if self.write_idx == 0 {
203	            // Pointer byte: low 2 bits select the register.
204	            self.pointer = byte & 0x03;
205	        } else {
206	            self.write_register_byte(self.pointer, self.write_idx, byte);
207	        }
208	        self.write_idx = self.write_idx.saturating_add(1);
209	        Ack::Ack
210	    }
211	
212	    fn on_read_byte(&mut self) -> u8 {
213	        let byte = self.read_register_byte(self.pointer, self.read_idx);
214	        self.read_idx = self.read_idx.wrapping_add(1);
215	        byte
216	    }
217	}
218	
219	/// Ergonomic extension on `I2cHandle<Tmp101Device>` so callers don't
220	/// need to spell out `handle.with(|d| d.set_temperature(c))`.
221	pub trait Tmp101HandleExt {
222	    fn set_temperature(&self, celsius: f32);
223	    fn temperature(&self) -> f32;
224	    fn set_resolution(&self, res: Tmp101Resolution);
225	    fn resolution(&self) -> Tmp101Resolution;
226	}
227	
228	impl Tmp101HandleExt for crate::peripherals::i2c::I2cHandle<Tmp101Device> {
229	    fn set_temperature(&self, celsius: f32) {
230	        self.with(|d| d.set_temperature(celsius));
231	    }
232	    fn temperature(&self) -> f32 {
233	        self.with(|d| d.temperature())
234	    }
235	    fn set_resolution(&self, res: Tmp101Resolution) {
236	        self.with(|d| d.set_resolution(res));
237	    }
238	    fn resolution(&self) -> Tmp101Resolution {
239	        self.with(|d| d.resolution())
240	    }
241	}
242	
