/// `Tmp101HandleExt` shape.
pub trait Ds1307HandleExt {
    fn set_time(&self, hour: u8, minute: u8, second: u8);
    fn set_date(&self, year: u8, month: u8, date: u8, day_of_week: u8);
    fn hour(&self) -> u8;
