/// Initialize the chip to the host's current wall-clock time (UTC),
/// using `SystemTime::now()`. Unlike `tick_second()` — which the brief
/// keeps leap-year-naive — this conversion does full leap-year math
/// because that's required to map Unix seconds back to a calendar
/// date correctly. Years map as DS1307 two-digit form: 2000→00,
/// 2026→26, ..., wrapping mod 100 past 2099.
pub fn set_to_system_time(&mut self) {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    self.set_from_unix_seconds(secs);
}

/// Backbone of `set_to_system_time`, separated so tests can pin a
/// fixed timestamp instead of depending on the host clock.
pub fn set_from_unix_seconds(&mut self, secs: u64) {
    let (year, month, date, dow, hour, minute, second) = decompose_unix_seconds(secs);
    self.set_date(year, month, date, dow);
    self.set_time(hour, minute, second);
}

