#[test]
fn build_ds1307_init_now_seeds_clock() {
    // Read the year register through the bus to confirm init=now
    // ran. Year stored as BCD; ≥0x25 means ≥2025, which is the
    // floor we ship at.
    let arc = build_i2c_device("ds1307@0x68?init=now").unwrap();
    let mut g = arc.lock().unwrap();
    g.on_start();
    assert_eq!(g.on_write_byte(0x06), crate::peripherals::i2c::Ack::Ack);
    g.on_start();
    let year_bcd = g.on_read_byte();
    assert!(
        year_bcd >= 0x25,
        "expected init=now to seed at least year 2025, got BCD {year_bcd:#04x}"
    );
}

