1	//! I2C address-routing table and CLI device registry stub.
2	//!
3	//! `AddressMap` is what the bus state machine consults on every byte
4	//! completion to decide whether to ACK and which device receives the
5	//! event. It is wrapped in `Arc<Mutex<...>>` so the typed `I2cHandle`
6	//! can refresh routing on `set_address`.
7	//!
8	//! `build_i2c_device` is the string-keyed registry the CLI will parse
9	//! (`add1@0x50`, `tmp101@0x4A`, ...). For now the only known device is
10	//! `add1`; additional devices land in their own steps.
11	
12	use std::collections::HashMap;
13	use std::sync::{Arc, Mutex};
14	
15	use super::device::I2cDevice;
16	use super::devices::add1::Add1Device;
17	use super::devices::ds1307::Ds1307Device;
18	use super::devices::tmp101::Tmp101Device;
19	
20	/// Inner storage of the routing table. Public to the crate so the
21	/// typed handle can mutate it on `set_address`.
22	#[derive(Default)]
23	pub struct AddressMapInner {
24	    pub entries: HashMap<u8, Arc<Mutex<dyn I2cDevice>>>,
25	}
26	
27	/// Shared address-routing table. Cloning shares the same allocation so
28	/// the bus state and any number of `I2cHandle`s see the same routing.
29	#[derive(Clone, Default)]
30	pub struct AddressMap {
31	    inner: Arc<Mutex<AddressMapInner>>,
32	}
33	
34	impl AddressMap {
35	    pub fn new() -> Self {
36	        Self::default()
37	    }
38	
39	    pub(crate) fn shared(&self) -> Arc<Mutex<AddressMapInner>> {
40	        self.inner.clone()
41	    }
42	
43	    /// Look up the device at `addr`, returning a fresh `Arc` clone so
44	    /// the caller can drop the table lock before locking the device.
45	    pub fn lookup(&self, addr: u8) -> Option<Arc<Mutex<dyn I2cDevice>>> {
46	        self.inner.lock().ok()?.entries.get(&addr).cloned()
47	    }
48	
49	    /// Insert the device at `addr`. Returns `Err(AddressInUse)` if the
50	    /// slot is already taken.
51	    pub(crate) fn insert(
52	        &self,
53	        addr: u8,
54	        dev: Arc<Mutex<dyn I2cDevice>>,
55	    ) -> Result<(), super::handle::AddressInUse> {
56	        let mut g = self.inner.lock().expect("I2C address table poisoned");
57	        if g.entries.contains_key(&addr) {
58	            return Err(super::handle::AddressInUse { address: addr });
59	        }
60	        g.entries.insert(addr, dev);
61	        Ok(())
62	    }
63	
64	    pub fn clear(&self) {
65	        if let Ok(mut g) = self.inner.lock() {
66	            g.entries.clear();
67	        }
68	    }
69	
70	    pub fn is_empty(&self) -> bool {
71	        self.inner
72	            .lock()
73	            .map(|g| g.entries.is_empty())
74	            .unwrap_or(true)
75	    }
76	
77	    pub fn len(&self) -> usize {
78	        self.inner.lock().map(|g| g.entries.len()).unwrap_or(0)
79	    }
80	}
