82	/// Parse a CLI device spec and construct the device, returning the
83	/// shared `Arc<Mutex<dyn I2cDevice>>` form the bus's address-routing
84	/// table holds. Callers wanting a typed handle should use
85	/// `EmulatorCore::attach_i2c_device(D::new(...))` directly instead.
86	///
87	/// Spec syntax: `<name>@<addr>[?key=val&...]`. Address is 7-bit hex
88	/// (`0x50` or `50`). Recognised devices:
89	///   - `add1@<addr>[?wrap=<n>]`             — universal +1 test slave.
90	///   - `tmp101@<addr>[?temp=<f>][?config=<n>]` — TI temp sensor.
91	///   - `ds1307@<addr>`                       — Dallas/Maxim RTC.
92	pub fn build_i2c_device(
93	    spec: &str,
94	) -> Result<std::sync::Arc<std::sync::Mutex<dyn I2cDevice>>, String> {
95	    use std::sync::{Arc, Mutex};
96	    let (name_addr, params) = match spec.split_once('?') {
97	        Some((head, tail)) => (head, Some(tail)),
98	        None => (spec, None),
99	    };
100	    let (name, addr_str) = name_addr
101	        .split_once('@')
102	        .ok_or_else(|| format!("device spec missing '@<addr>': {spec}"))?;
103	    let addr = parse_addr(addr_str)
104	        .ok_or_else(|| format!("invalid 7-bit address in spec '{spec}'"))?;
105	    match name {
106	        "add1" => {
107	            let mut wrap: u16 = 0x100;
108	            if let Some(p) = params {
109	                for kv in p.split('&') {
110	                    let (k, v) = kv
111	                        .split_once('=')
112	                        .ok_or_else(|| format!("bad param '{kv}' in '{spec}'"))?;
113	                    match k {
114	                        "wrap" => {
115	                            wrap = v.parse().map_err(|e| format!("bad wrap '{v}': {e}"))?
116	                        }
117	                        _ => return Err(format!("unknown add1 param '{k}' in '{spec}'")),
118	                    }
119	                }
120	            }
121	            Ok(Arc::new(Mutex::new(Add1Device::new(addr, wrap))))
122	        }
123	        "tmp101" => {
124	            let mut dev = Tmp101Device::new(addr);
125	            if let Some(p) = params {
126	                for kv in p.split('&') {
127	                    let (k, v) = kv
128	                        .split_once('=')
129	                        .ok_or_else(|| format!("bad param '{kv}' in '{spec}'"))?;
130	                    match k {
131	                        "temp" => {
132	                            let c: f32 =
133	                                v.parse().map_err(|e| format!("bad temp '{v}': {e}"))?;
134	                            dev.set_temperature(c);
135	                        }
136	                        "config" => {
137	                            let c: u8 = if let Some(rest) =
138	                                v.strip_prefix("0x").or_else(|| v.strip_prefix("0X"))
139	                            {
140	                                u8::from_str_radix(rest, 16)
141	                                    .map_err(|e| format!("bad config '{v}': {e}"))?
142	                            } else {
143	                                v.parse().map_err(|e| format!("bad config '{v}': {e}"))?
144	                            };
145	                            dev.set_config(c);
146	                        }
147	                        _ => return Err(format!("unknown tmp101 param '{k}' in '{spec}'")),
148	                    }
149	                }
150	            }
151	            Ok(Arc::new(Mutex::new(dev)))
152	        }
153	        "ds1307" => {
154	            if let Some(p) = params
155	                && let Some(kv) = p.split('&').next()
156	            {
157	                let (k, _) = kv
158	                    .split_once('=')
159	                    .ok_or_else(|| format!("bad param '{kv}' in '{spec}'"))?;
160	                return Err(format!("unknown ds1307 param '{k}' in '{spec}'"));
161	            }
162	            Ok(Arc::new(Mutex::new(Ds1307Device::new(addr))))
163	        }
164	        other => Err(format!("unknown I2C device '{other}'")),
165	    }
166	}
167	
168	fn parse_addr(s: &str) -> Option<u8> {
169	    let s = s.trim();
170	    let n: u32 = if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
171	        u32::from_str_radix(stripped, 16).ok()?
172	    } else {
173	        s.parse().ok()?
174	    };
175	    if n > 0x7F { None } else { Some(n as u8) }
176	}
