1	//! `ds1307` — Maxim/Dallas DS1307 real-time clock (I2C).
2	//!
3	//! Eight BCD registers behind an auto-incrementing pointer, exactly as
4	//! the datasheet describes. The web UI's RTC panel reads/writes them
5	//! through the same bit-bang path a real master would use, so this
6	//! device mirrors the chip's protocol rather than offering a friendly
7	//! out-of-band interface.
8	//!
9	//! Pointer mapping (`pointer & 0x07`):
10	//!   - `0x00` — Seconds (00–59 BCD). Bit 7 = CH (Clock Halt) — masked
11	//!     out on writes so the emulated clock keeps ticking regardless.
12	//!   - `0x01` — Minutes (00–59 BCD).
13	//!   - `0x02` — Hours (00–23 BCD). Bit 6 = 12/24 mode; this device
14	//!     stores 24-hour format.
15	//!   - `0x03` — Day of Week (1–7 BCD).
16	//!   - `0x04` — Date (01–31 BCD).
17	//!   - `0x05` — Month (01–12 BCD).
18	//!   - `0x06` — Year (00–99 BCD).
19	//!   - `0x07` — Control. Stored verbatim; the SQW/RAM/OUT bits don't
20	//!     affect timekeeping in this emulation.
21	
22	use crate::peripherals::i2c::device::{Ack, I2cDevice};
23	
24	/// Default 7-bit address for the DS1307.
25	pub const DEFAULT_ADDRESS: u8 = 0x68;
26	
27	const REG_SECONDS: usize = 0;
28	const REG_MINUTES: usize = 1;
29	const REG_HOURS: usize = 2;
30	const REG_DAY_OF_WEEK: usize = 3;
31	const REG_DATE: usize = 4;
32	const REG_MONTH: usize = 5;
33	const REG_YEAR: usize = 6;
34	const REG_CONTROL: usize = 7;
35	
36	const CH_BIT: u8 = 0x80;
37	
38	pub struct Ds1307Device {
39	    address: u8,
40	    pointer: u8,
41	    /// Byte index within the current write transaction. 0 = next byte
42	    /// is the pointer load; 1+ = data bytes for `regs[pointer]`.
43	    write_idx: u8,
44	    /// Eight BCD registers: [sec, min, hr, dow, date, month, year, ctrl].
45	    regs: [u8; 8],
46	}
47	
48	impl Ds1307Device {
49	    pub fn new(address: u8) -> Self {
50	        Self {
51	            address: address & 0x7F,
52	            pointer: 0,
53	            write_idx: 0,
54	            regs: [0; 8],
55	        }
56	    }
57	
58	    /// Set the time-of-day in 24-hour binary form. Out-of-range values
59	    /// are clamped to the chip's permitted ranges before BCD-encoding.
60	    pub fn set_time(&mut self, hour: u8, minute: u8, second: u8) {
61	        // Clear CH on every set so the clock starts ticking from this
62	        // moment regardless of what the master had written earlier.
63	        self.regs[REG_SECONDS] = int_to_bcd(second.min(59));
64	        self.regs[REG_MINUTES] = int_to_bcd(minute.min(59));
65	        self.regs[REG_HOURS] = int_to_bcd(hour.min(23)); // bit 6 stays 0 = 24-hour
66	    }
67	
68	    /// Set the calendar in binary form.
69	    pub fn set_date(&mut self, year: u8, month: u8, date: u8, day_of_week: u8) {
70	        self.regs[REG_YEAR] = int_to_bcd(year.min(99));
71	        self.regs[REG_MONTH] = int_to_bcd(month.clamp(1, 12));
72	        self.regs[REG_DATE] = int_to_bcd(date.clamp(1, 31));
73	        self.regs[REG_DAY_OF_WEEK] = int_to_bcd(day_of_week.clamp(1, 7));
74	    }
75	
76	    pub fn second(&self) -> u8 {
77	        bcd_to_int(self.regs[REG_SECONDS] & !CH_BIT)
78	    }
79	
80	    pub fn minute(&self) -> u8 {
81	        bcd_to_int(self.regs[REG_MINUTES])
82	    }
83	
84	    pub fn hour(&self) -> u8 {
85	        // Mask off the 12/24 + AM/PM bits — this device runs in 24-hour
86	        // mode but a master could write bit 6 / bit 5; reporting plain
87	        // binary hours keeps the panel readout sane.
88	        bcd_to_int(self.regs[REG_HOURS] & 0x3F)
89	    }
90	
91	    pub fn day_of_week(&self) -> u8 {
92	        bcd_to_int(self.regs[REG_DAY_OF_WEEK] & 0x07)
93	    }
94	
95	    pub fn date(&self) -> u8 {
96	        bcd_to_int(self.regs[REG_DATE] & 0x3F)
97	    }
98	
99	    pub fn month(&self) -> u8 {
100	        bcd_to_int(self.regs[REG_MONTH] & 0x1F)
101	    }
102	
103	    pub fn year(&self) -> u8 {
104	        bcd_to_int(self.regs[REG_YEAR])
105	    }
106	
107	    pub fn control(&self) -> u8 {
108	        self.regs[REG_CONTROL]
109	    }
110	
111	    /// Snapshot of the eight raw register bytes, useful for tests and
112	    /// for the web panel's "show me everything" view.
113	    pub fn registers(&self) -> [u8; 8] {
114	        self.regs
115	    }
116	
117	    /// Advance the clock by one second, cascading into minutes, hours,
118	    /// day-of-week, date, month, and year as needed. Leap-year handling
119	    /// is intentionally deferred — February is fixed at 28 days per the
120	    /// brief.
121	    pub fn tick_second(&mut self) {
122	        let mut sec = self.second();
123	        let mut min = self.minute();
124	        let mut hr = self.hour();
125	        let mut dow = self.day_of_week();
126	        let mut date = self.date();
127	        let mut month = self.month();
128	        let mut year = self.year();
129	
130	        sec += 1;
131	        if sec >= 60 {
132	            sec = 0;
133	            min += 1;
134	            if min >= 60 {
135	                min = 0;
136	                hr += 1;
137	                if hr >= 24 {
138	                    hr = 0;
139	                    dow = if dow >= 7 { 1 } else { dow + 1 };
140	                    date += 1;
141	                    if date > days_in_month(month) {
142	                        date = 1;
143	                        month += 1;
144	                        if month > 12 {
145	                            month = 1;
146	                            year = (year + 1) % 100;
147	                        }
148	                    }
149	                }
150	            }
151	        }
152	
153	        self.regs[REG_SECONDS] = int_to_bcd(sec);
154	        self.regs[REG_MINUTES] = int_to_bcd(min);
155	        self.regs[REG_HOURS] = int_to_bcd(hr);
156	        self.regs[REG_DAY_OF_WEEK] = int_to_bcd(dow);
157	        self.regs[REG_DATE] = int_to_bcd(date);
158	        self.regs[REG_MONTH] = int_to_bcd(month);
159	        self.regs[REG_YEAR] = int_to_bcd(year);
160	    }
161	}
162	
163	fn int_to_bcd(n: u8) -> u8 {
164	    ((n / 10) << 4) | (n % 10)
165	}
166	
167	fn bcd_to_int(b: u8) -> u8 {
168	    ((b >> 4) * 10) + (b & 0x0F)
169	}
170	
171	fn days_in_month(month: u8) -> u8 {
172	    match month {
173	        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
174	        4 | 6 | 9 | 11 => 30,
175	        2 => 28,
176	        _ => 31,
177	    }
178	}
