        // confirms the address byte parsed correctly.
        assert!(bus_write_byte(&mut cpu, 0x50 << 1));
        assert_eq!(cpu.io.i2c.current_target, Some(0x50));
        assert_eq!(cpu.io.i2c.current_dir, I2cDir::Write);
    }
}

