1	//! `echo` — universal SPI test slave.
2	//!
3	//! Smallest device that exercises the bus's per-byte dispatch end to
4	//! end. Stores a single-byte buffer holding "what to drive on MISO
5	//! during the next exchange". On every byte the master clocks in,
6	//! the buffer is replaced with that MOSI byte; the next exchange then
7	//! drives it back out. Net effect: MISO byte N+1 == MOSI byte N — the
8	//! one-byte delay a real hardware shift register exhibits, since the
9	//! slave needs the byte loaded before the master clocks bit 0.
10	//!
11	//! On `on_select` the device returns its current buffer (the seed for
12	//! the very first exchange after CS goes low).
13	
14	use crate::peripherals::spi::device::SpiDevice;
15	
16	pub struct EchoDevice {
17	    /// Byte the slave will drive on MISO during the next 8-clock
18	    /// exchange. Updated by `on_byte` (latches MOSI for next time) and
19	    /// by `poke` (test/UI control).
20	    buffer: u8,
21	}
22	
23	impl EchoDevice {
24	    /// Construct an EchoDevice with the given seed byte. The seed is
25	    /// what the slave drives on MISO during the *first* exchange after
26	    /// `on_select`.
27	    pub fn new(seed: u8) -> Self {
28	        Self { buffer: seed }
29	    }
30	
31	    /// Inspect the buffered byte without touching it.
32	    pub fn peek(&self) -> u8 {
33	        self.buffer
34	    }
35	
36	    /// Force the buffered byte. The next exchange will return this
37	    /// value on MISO.
38	    pub fn poke(&mut self, value: u8) {
39	        self.buffer = value;
40	    }
41	}
42	
43	impl SpiDevice for EchoDevice {
44	    fn name(&self) -> &str {
45	        "echo"
46	    }
47	
48	    fn on_select(&mut self) -> u8 {
49	        self.buffer
50	    }
51	
52	    fn on_byte(&mut self, mosi: u8) -> u8 {
53	        // Latch the just-clocked MOSI byte; the bus then drives it out
54	        // on the *next* exchange — a one-byte echo delay.
55	        self.buffer = mosi;
56	        self.buffer
57	    }
58	}
59	
60	#[cfg(test)]
61	mod tests {
62	    use super::*;
63	
64	    #[test]
65	    fn name_default() {
66	        let d = EchoDevice::new(0x00);
67	        assert_eq!(d.name(), "echo");
68	    }
69	
70	    #[test]
71	    fn on_select_returns_seed() {
72	        let mut d = EchoDevice::new(0xA5);
73	        assert_eq!(d.on_select(), 0xA5);
74	    }
75	
76	    #[test]
77	    fn on_byte_latches_mosi_for_next_exchange() {
78	        // The trait contract is: on_byte returns the byte the slave
79	        // will drive on MISO during the *next* exchange. EchoDevice
80	        // satisfies that by latching the just-clocked MOSI byte and
81	        // returning it — the bus then uses that as next current_miso.
82	        let mut d = EchoDevice::new(0x11);
83	        // First on_byte: latch 0x42; next exchange will drive 0x42.
84	        assert_eq!(d.on_byte(0x42), 0x42);
85	        // Second on_byte: latch 0x99; next exchange will drive 0x99.
