                        _ => return Err(format!("unknown sdcard param '{k}' in '{spec}'")),
                    }
                }
            }
            let dev = if let Some(path) = file {
                SdCardDevice::from_file(&path, cs)
                    .map_err(|e| format!("sdcard file '{}': {e}", path.display()))?
            } else {
